<span class="line"><span style="color:#F97583;">    server</span><span style="color:#E1E4E8;"> 192.168.3.11:8080 </span><span style="color:#FFAB70;">max_fails</span><span style="color:#F97583;">=</span><span style="color:#79B8FF;">3</span><span style="color:#E1E4E8;"> fail_timeout=30s;</span></span>
